const floatingBack=document.querySelector('.floating-back');const hideThreshold=120;const updateFloatingBack=()=>{if(!floatingBack)return;floatingBack.classList.toggle('is-hidden',window.scrollY>hideThreshold);};const devPopup=document.getElementById('devPopup');const closePopupButton=document.querySelector('.popup-close');const closePopup=()=>{devPopup.classList.remove('visible');devPopup.setAttribute('aria-hidden','true');};closePopupButton.addEventListener('click',closePopup);document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&devPopup.classList.contains('visible')){closePopup();}});document.querySelectorAll('.card').forEach((card)=>{if(card.classList.contains('inactive')){const showPopup=()=>{const rect=card.getBoundingClientRect();const popupWidth=devPopup.offsetWidth||320;const popupHeight=devPopup.offsetHeight||150;const left=Math.min(Math.max(rect.left+rect.width/2,popupWidth/2+24),window.innerWidth-popupWidth/2-24);const top=Math.min(Math.max(rect.top+rect.height/2,popupHeight/2+24),window.innerHeight-popupHeight/2-24);devPopup.style.left=`${left}px`;devPopup.style.top=`${top}px`;devPopup.classList.add('visible');devPopup.setAttribute('aria-hidden','false');};card.addEventListener('click',showPopup);card.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showPopup();}});return;}const link=card.dataset.href;if(!link)return;const openCard=(event)=>{if(event.target.closest('a'))return;window.open(link,'_blank','noopener,noreferrer');};card.addEventListener('click',openCard);card.addEventListener('keydown',(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();window.open(link,'_blank','noopener,noreferrer');}});});window.addEventListener('scroll',updateFloatingBack,{passive:true});updateFloatingBack();